function findIcdByCode(code) { return ICD10_REGISTRY.find(i => i.code.toLowerCase() === code.toLowerCase().trim()); }
function getIcdByChapter(chapter) { return ICD10_REGISTRY.filter(i => i.chapter.toLowerCase().includes(chapter.toLowerCase())); }
function getRecommendedTestsForDiagnosis(code) {
  const entry = findIcdByCode(code);
  return entry ? entry.recommendedLabTests : ["Routine Diagnostic Screen"];
}

module.exports = { ICD10_REGISTRY, findIcdByCode, getIcdByChapter, getRecommendedTestsForDiagnosis };